{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "weaken",
  "supportive_card_ids": ["C129", "C130", "C150", "C162", "C167", "C61", "C49", "C46", "C182", "C189", "C215", "C180"],
  "contradictory_card_ids": ["C191", "C200", "C211", "C219", "C194"],
  "prediction_basis_card_ids": ["C129", "C130", "C150", "C162", "C167", "C61", "C49", "C46"],
  "claims": [
    {
      "claim": "L4 records for sulfonylurea analogs show high intestinal absorption: glipizide FA >95% (C129), glimepiride almost completely absorbed (C130), and high Caco-2 Papp for glipizide (~10×10^-6 cm/s; C150, C162) and glibenclamide (18.1×10^-6 cm/s; C167), supporting that the query's acidic sulfonyl semicarbazide can be absorbed despite ionization.",
      "card_ids": ["C129", "C130", "C150", "C162", "C167"]
    },
    {
      "claim": "L5 records show glibenclamide is a P-gp/BCRP substrate with efflux ratios ~2.4-4 (C191, C200, C219, C211) and tolbutamide undergoes intestinal CYP2C9 metabolism (C194), providing mechanistic context for possible presystemic loss in sulfonylurea-like compounds; none of these records reports F<20% and the query was not directly tested.",
      "card_ids": ["C191", "C200", "C211", "C219", "C194"]
    },
    {
      "claim": "Other L5 records show sulfonamide/sulfone-containing compounds with high Caco-2 permeability and efflux ratios near 1 (C182, C189, C215, C180), indicating that efflux is not a universal barrier in this chemotype and mitigating the negative mechanistic signal.",
      "card_ids": ["C182", "C189", "C215", "C180"]
    },
    {
      "claim": "Prior human absolute-bioavailability contexts (zolpidem ~68-70%, C61; solifenacin 88%, C49; quinapril ~50%, C46) remain supportive of F>=20% for small oral drugs, though transferability is structural rather than direct.",
      "card_ids": ["C61", "C49", "C46"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C191", "C200", "C211", "C219", "C194"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the query molecule.",
    "No query-specific permeability, efflux, or intestinal metabolism data.",
    "L5 records are for sulfonylurea analogs (glibenclamide, tolbutamide) and other sulfonamides, not the query; the semicarbazide vs urea and the bicyclic amine may alter transporter/enzyme interactions.",
    "First-pass hepatic metabolism and systemic clearance for the query are unmeasured.",
    "The query's low neutral fraction and logD remain physicochemical concerns, not endpoint proof.",
    "No human PK, dose, formulation, or route data for the query."
  ],
  "decision_summary": "L5 gut-wall efflux/intestinal-metabolism records add mechanistic context for possible presystemic loss in sulfonylurea-like analogs (glibenclamide P-gp/BCRP substrate; tolbutamide intestinal CYP2C9 metabolism), but they do not provide affirmative evidence of F<20% and are outweighed by L4 absorption/permeability evidence for the sulfonylurea chemotype and by prior human F contexts; F>=20% remains better supported, though with reduced strength."
}

